import { View, Image } from '@tarojs/components'
import Taro from '@tarojs/taro'

const IS_WEAPP = Taro.getEnv() === Taro.ENV_TYPE.WEAPP

const ICON_BASE64: Record<string, Record<string, string>> = {
  home: {
    default:
      'data:image/svg+xml;base64,',
    active:
      'data:image/svg+xml;base64,',
  },
  mall: {
    default:
      'data:image/svg+xml;base64,',
    active:
      'data:image/svg+xml;base64,',
  },
  plus: {
    default:
      'data:image/svg+xml;base64,',
    active:
      'data:image/svg+xml;base64,',
  },
  message: {
    default:
      'data:image/svg+xml;base64,',
    active:
      'data:image/svg+xml;base64,',
  },
  user: {
    default:
      'data:image/svg+xml;base64,',
    active:
      'data:image/svg+xml;base64,',
  },
  search: {
    default:
      'data:image/svg+xml;base64,',
    active:
      'data:image/svg+xml;base64,',
  },
  heart: {
    default:
      'data:image/svg+xml;base64,',
    active:
      'data:image/svg+xml;base64,',
  },
  'user-placeholder': {
    default:
      'data:image/svg+xml;base64,',
    active:
      'data:image/svg+xml;base64,',
  },
}

interface IconProps {
  name: keyof typeof ICON_BASE64
  size?: number
  className?: string
}

export default function Icon({ name, size = 22, className }: IconProps) {
  if (IS_WEAPP) {
    return (
      <Image
        src={ICON_BASE64[name]?.default || ''}
        style={{ width: `${size}px`, height: `${size}px` }}
        className={className}
        mode='aspectFit'
      />
    )
  }

  return <View className={className} />
}

export { ICON_BASE64, IS_WEAPP }
